let ctx,master;const cache=new Map,pending=new Map,seen=new Map;
function unlock(){if(!ctx){ctx=new AudioContext;master=ctx.createGain();master.gain.value=.34;master.connect(ctx.destination);for(const f of ['shot3.mp3','shot4.mp3','shot5.wav','auto1.mp3','auto2.mp3','shotgun2.wav','reload.mp3','explosion5.wav'])load(f)}ctx.resume()}
async function load(f){if(cache.has(f))return cache.get(f);if(pending.has(f))return pending.get(f);const p=fetch(base+f,{credentials:'same-origin'}).then(r=>{if(!r.ok)throw Error(r.status);return r.arrayBuffer()}).then(a=>ctx.decodeAudioData(a)).then(b=>(cache.set(f,b),b)).catch(()=>null).finally(()=>pending.delete(f));pending.set(f,p);return p}
function onset(b){const d=b.getChannelData(0),step=128,limit=Math.min(d.length,b.sampleRate*2),r=[];let max=0;for(let i=0;i<limit-step;i+=step){let n=0;for(let j=0;j<step;j++){const v=d[i+j];n+=v*v}n=Math.sqrt(n/step);r.push(n);max=Math.max(max,n)}const k=r.findIndex(v=>v>max*.18);return Math.max(0,(k<0?0:k*step)/b.sampleRate-.012)}
function playFile(f,o={}){if(!ctx||!master)return;const b=cache.get(f);if(!b){load(f).then(x=>x&&playFile(f,o));return}const src=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain(),pan=ctx.createStereoPanner(),now=ctx.currentTime,dist=Math.max(0,o.distance||0),range=o.suppressed?52:190,fall=Math.max(0,1-dist/range);if(fall<.002)return;src.buffer=b;src.playbackRate.value=(o.pitch||1)*(.99+Math.random()*.02);filter.type=o.suppressed?'lowpass':'highpass';filter.frequency.value=o.suppressed?1600:25;filter.Q.value=.5;gain.gain.setValueAtTime(Math.min(1.3,(o.gain||1)*fall*(o.suppressed?.42:1)),now);pan.pan.value=Math.max(-1,Math.min(1,o.pan||0));src.connect(filter).connect(gain).connect(pan).connect(master);const start=o.trim?onset(b):0,dur=o.trim?.105:Math.min(b.duration,o.duration||1.35);if(o.trim)gain.gain.exponentialRampToValueAtTime(.001,now+dur);src.start(now,start,dur);src.stop(now+dur+.02)}
function gunshot(o={}){unlock();if(o.eventKey){const n=performance.now(),v=seen.get(o.eventKey);if(v&&n-v<1500)return;seen.set(o.eventKey,n)}const a=map[o.ammoId]||map['ammo-556'];let pitch=a[2],gain=a[1],w=String(o.weaponId||'').toLowerCase();if(w.includes('awm')){pitch*=.92;gain*=1.1}if(w.includes('lynx')){pitch*=.82;gain*=1.2}playFile(a[0],{gain,pitch,trim:!!a[3],suppressed:!!o.suppressed,distance:o.distance,pan:o.pan})}
